window.LESSONS={"speakers": {"YF": "20대 여성", "YM": "20대 남성", "MM": "중년 남성", "MF": "중년 여성", "OLD": "어르신", "WH_GB": "워홀러 (영국)", "WH_GB2": "워홀러 (영국)", "WH_FR": "워홀러 (프랑스)", "WH_IE": "워홀러 (아일랜드)", "WH_IT": "워홀러 (이탈리아)", "WH_KR": "워홀러 (한국)", "WH_DE": "워홀러 (독일)", "IN_DRV": "택시·우버 기사 (인도계)", "IN_SHOP": "점원 (인도계)"}, "speaker_notes": [["20대 여성", "말 빠르고 끝이 올라가요(\"...today?↗\"). Oh my god, totally, so 같은 감탄이 많아요."], ["20대 남성", "mate, all good, sweet, legend. 단어를 짧게 끊어요(goin', 'em)."], ["중년 남성", "G'day, no dramas, the go. 억양이 가장 '호주스러워요'."], ["중년 여성", "love를 자주 붙여요(\"Are you right, love?\"). 친절하고 또박또박."], ["어르신", "dear, dears. 천천히, 정중하게. 길을 아주 자세히 알려줘요."], ["워홀러 점원", "호주 정부 통계(2024-25 워홀 비자 발급 32만 건)로 보면 영국 25%, 프랑스 13%, 아일랜드 8%, 이탈리아 6%, 한국 5%, 대만·일본·독일 각 5% 순이에요. 그래서 이 자료의 워홀러 대사도 영국 16 · 프랑스 5 · 아일랜드 5 · 한국 3 · 이탈리아 3 · 독일 3 비율로 넣었어요. 시드니 카페·식당에선 영국·아일랜드 억양을 가장 자주 듣게 돼요. 도시별 통계는 따로 없고 전국 수치예요."], ["인도계 기사·점원", "워홀러는 적지만, 2021년 인구조사에서 시드니 주민의 3.6%가 인도 출생(중국 다음 2위)이에요. 택시·우버 기사나 편의점·가게 점원에게서 자주 들어요. 말이 빠르고 r을 굴리며, t·d를 혀끝으로 또렷하게 끊어요."]], "sections": [{"num": "0", "title": "인사 · 기본 리액션", "lead": "호주에선 점원·기사님·옆 사람까지 다 먼저 말을 걸어요. 질문 형태는 제각각이어도 대답은 하나면 돼요.", "units": [{"situation": "가게 들어가면 듣는 인사 (잘 지내요?)", "order": "they", "speak": {"en": "Good, thanks. How are you?", "ko": "좋아요, 그쪽은요?", "tip": "어떤 인사가 와도 이 한 문장. 'How ya going?'은 '어디 가냐'가 아니에요", "audio": "audio/cc5a0b81a9.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Hiii, how are we today?", "ko": "안녕하세요~ 오늘 어떠세요?", "audio": "audio/da9451055b.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Hey, how's it goin'?", "ko": "안녕, 잘 지내요?", "audio": "audio/330cea54c0.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "G'day, how ya goin', mate?", "ko": "안녕하쇼, 잘 지내요?", "audio": "audio/c2241ecace.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Hello love, how are you going?", "ko": "어서 와요, 잘 지내요?", "audio": "audio/b219787ebd.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Good morning, dear. Lovely day, isn't it?", "ko": "좋은 아침이에요. 날씨 좋죠?", "audio": "audio/9df8bb4d2c.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "Hiya, you alright?", "ko": "안녕하세요, 잘 지내요?", "audio": "audio/8b4e54d810.mp3"}]}, {"situation": "고맙다고 했을 때 돌아오는 말", "order": "me", "speak": {"en": "Thanks so much!", "ko": "정말 고마워요!", "tip": "Cheers! 도 좋아요", "audio": "audio/0196437049.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "No worries!", "ko": "천만에요!", "audio": "audio/6e2f1443ae.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "All good, mate.", "ko": "괜찮아요.", "audio": "audio/509713f566.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "No dramas.", "ko": "별말을요.", "audio": "audio/903352789f.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "You're welcome, love.", "ko": "천만에요.", "audio": "audio/172f5a90a3.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "My pleasure, dear.", "ko": "제가 좋아서 한 건데요.", "audio": "audio/d58dfb35fb.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "No problem!", "ko": "문제없어요!", "audio": "audio/2d964eafd8.mp3"}]}, {"situation": "못 알아들었을 때", "order": "me", "speak": {"en": "Sorry, I didn't catch that.", "ko": "죄송해요, 못 알아들었어요.", "tip": "Sorry? 한 마디도 OK. 대부분 천천히 다시 말해줘요", "audio": "audio/aafe17de2a.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Oh sorry! I said, is that for here?", "ko": "아 미안해요! 여기서 드시냐고요.", "audio": "audio/24882395af.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "No worries. Eat in or takeaway?", "ko": "괜찮아요. 먹고 가요, 가져가요?", "audio": "audio/270abd910b.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "I'm sorry, dear, I'll speak up.", "ko": "미안해요, 크게 말할게요.", "audio": "audio/0a12c8df38.mp3"}]}, {"situation": "가게 나올 때 듣는 인사", "order": "they", "speak": {"en": "You too, thanks!", "ko": "그쪽도요, 고마워요!", "tip": "Have a good one = 좋은 하루 보내요. 대답은 늘 You too", "audio": "audio/984451c38b.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Have a good one!", "ko": "좋은 하루 보내요!", "audio": "audio/e1b4d8680e.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "See ya, mate. Enjoy!", "ko": "잘 가요, 즐겨요!", "audio": "audio/26bb0342c3.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Cheers, have a good arvo.", "ko": "고마워요, 좋은 오후 보내요.", "audio": "audio/ca91a8d0bc.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Enjoy the rest of your day, love.", "ko": "남은 하루 잘 보내요.", "audio": "audio/de3654be00.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Take care now, dears.", "ko": "조심히 가요.", "audio": "audio/52ca5afb36.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "Have a lovely day!", "ko": "좋은 하루 보내세요!", "audio": "audio/de4954298e.mp3"}]}, {"situation": "좁은 데서 지나갈 때 · 부딪혔을 때", "order": "me", "speak": {"en": "Sorry, can I just squeeze past?", "ko": "죄송한데 좀 지나갈게요.", "tip": "'You're right!' = 괜찮아요. '도와드릴까요?'가 아니에요", "audio": "audio/01d19f3fea.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Oh, you're right!", "ko": "아, 괜찮아요!", "audio": "audio/0dc181cc60.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "All good, mate.", "ko": "괜찮아요.", "audio": "audio/509713f566.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "You're right, mate, go for it.", "ko": "괜찮아요, 지나가요.", "audio": "audio/e5a5a35ce8.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Oh, sorry, love, I'm in the way.", "ko": "어머, 제가 막고 있었네요.", "audio": "audio/79608230d1.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Not at all, dear.", "ko": "괜찮아요.", "audio": "audio/a44d328b35.mp3"}]}, {"situation": "어디서 왔어요?", "order": "they", "speak": {"en": "We're from Korea, here on our honeymoon.", "ko": "한국에서 왔어요, 신혼여행 중이에요.", "tip": "Seoul 근처라고 하면 대화가 더 이어져요", "audio": "audio/40c55f00b3.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Where are you guys from?", "ko": "어디서 오셨어요?", "audio": "audio/cacbe32589.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "You on holidays?", "ko": "여행 중이에요?", "audio": "audio/3071d25b72.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Where ya from, mate?", "ko": "어디서 왔어요?", "audio": "audio/da1cd44f65.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Where's home for you two?", "ko": "두 분 어디 사세요?", "audio": "audio/ddd3ec3835.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Are you visiting, dears?", "ko": "여행 오셨어요?", "audio": "audio/1104970b2c.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Are you here travelling?", "ko": "여행 오신 거예요?", "audio": "audio/4b00b6d9d5.mp3"}]}]}, {"num": "1", "title": "화장실 찾을 때", "lead": "호주는 restroom보다 toilets. 직설적으로 물어도 전혀 무례하지 않아요.", "units": [{"situation": "화장실이 어디예요?", "order": "me", "speak": {"en": "Sorry, where are the toilets?", "ko": "저기요, 화장실 어디예요?", "tip": "Sorry = Excuse me. 호주에선 말 걸 때 Sorry를 많이 써요", "audio": "audio/5ce163a506.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Just down the back, on your left!", "ko": "안쪽 끝, 왼쪽이에요!", "audio": "audio/c15cfbeb2d.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yeah, out the back, mate.", "ko": "뒤쪽이에요.", "audio": "audio/d799f0fa44.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Through there, past the bar, first door on the right.", "ko": "저리로 가서 바 지나 오른쪽 첫 문이요.", "audio": "audio/57d32bf345.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "They're just upstairs, love.", "ko": "위층이에요.", "audio": "audio/6bd3a8166d.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Go right to the end, dear, then turn left.", "ko": "끝까지 가서 왼쪽으로 돌아요.", "audio": "audio/4c789d6874.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Ehm, behind the counter, just there.", "ko": "음, 카운터 뒤 저기요.", "audio": "audio/c6a6ca95dd.mp3"}]}, {"situation": "카페 화장실 써도 돼요?", "order": "me", "speak": {"en": "Mind if I use your toilet?", "ko": "화장실 좀 써도 될까요?", "tip": "먼저 커피 하나 사면 더 자연스러워요", "audio": "audio/58b7dcd3b0.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yeah, of course, go for it!", "ko": "그럼요, 쓰세요!", "audio": "audio/1730fe48f2.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Sorry mate, customers only.", "ko": "죄송한데 손님만 돼요.", "audio": "audio/398dc3637a.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Yeah, no worries. Code's on your receipt.", "ko": "그럼요. 비밀번호는 영수증에 있어요.", "audio": "audio/7d2a41fd0d.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Sure, love, the key's just on the hook there.", "ko": "네, 열쇠는 저 고리에 있어요.", "audio": "audio/58b0eb542a.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "Sorry, it's only for paying customers.", "ko": "죄송한데 결제한 손님만요.", "audio": "audio/bff54063f9.mp3"}]}, {"situation": "근처에 공중화장실 있어요?", "order": "me", "speak": {"en": "Are there any public toilets around here?", "ko": "근처에 공중화장실 있어요?", "tip": "공원·해변은 'Amenities' 표지", "audio": "audio/f75629e9bb.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "Yeah, there's some in the park, just over there.", "ko": "네, 저기 공원에 있어요.", "audio": "audio/dccc712e31.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Try Westfield, love, there's toilets on level two.", "ko": "웨스트필드 가보세요, 2층에 있어요.", "audio": "audio/44e7f324fb.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "There's one at the station, dear.", "ko": "역에 하나 있어요.", "audio": "audio/da78a8df69.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Nearest one's down by the beach, near the surf club.", "ko": "제일 가까운 건 해변 서프클럽 옆이요.", "audio": "audio/2bf6df25a1.mp3"}]}, {"situation": "화장실이 잠겨 있어요 (비밀번호 · 열쇠)", "order": "me", "speak": {"en": "Sorry, the toilet's locked. Is there a code?", "ko": "화장실이 잠겼는데 비밀번호 있어요?", "tip": "쇼핑센터·카페 화장실은 비밀번호나 열쇠가 많아요", "audio": "audio/c35961385b.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Oh yeah, it's two-five-eight-oh!", "ko": "아 네, 2580이에요!", "audio": "audio/d652dcfd8c.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Code's on the bottom of your receipt, mate.", "ko": "영수증 아래에 있어요.", "audio": "audio/4c94324e52.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Here's the key, love. Just bring it back after.", "ko": "열쇠 여기요. 쓰고 돌려주세요.", "audio": "audio/6964a1d85b.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "Code is on the door, sir. One-two-three-four.", "ko": "문에 적혀 있어요. 1234요.", "audio": "audio/e602c29e4f.mp3"}, {"speaker": "WH_DE", "speaker_label": "워홀러 (독일)", "en": "Ah, you need the key. I get it for you.", "ko": "열쇠 필요해요. 갖다 드릴게요.", "audio": "audio/c4bd63a2c3.mp3"}]}, {"situation": "여자·남자 화장실 어느 쪽?", "order": "me", "speak": {"en": "Which one's the ladies'?", "ko": "여자 화장실은 어느 쪽이에요?", "tip": "ladies' = 여자, gents' = 남자, accessible = 장애인용", "audio": "audio/951d01ae5b.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Ladies' is on the left, gents' on the right.", "ko": "여자는 왼쪽, 남자는 오른쪽이요.", "audio": "audio/2d08076006.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "That one's the gents'. Ladies' is round the corner.", "ko": "거긴 남자 거예요. 여자는 모퉁이 돌아서요.", "audio": "audio/7750546bfb.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "That's the accessible one, love. Ladies' is next door.", "ko": "거긴 장애인용이고 여자는 옆이에요.", "audio": "audio/6b9bd56788.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "The one with the little lady on it, dear.", "ko": "여자 그림 있는 쪽이에요.", "audio": "audio/cbebea1c12.mp3"}]}]}, {"num": "2", "title": "길 물어볼 때", "lead": "대답은 사람마다 제각각이지만 핵심 단어는 몇 개뿐이에요: the lights(신호등), head down(쭉 가다), a bit of a hike(꽤 멀다).", "units": [{"situation": "서큘러 키 어느 쪽이에요?", "order": "me", "speak": {"en": "Sorry, which way's Circular Quay?", "ko": "저기요, 서큘러 키 어느 쪽이에요?", "tip": "Quay는 '키'. 목적지만 바꿔서 계속 쓰세요", "audio": "audio/b5c10f6a5f.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Oh, just head straight down George Street, you can't miss it.", "ko": "조지 스트리트로 쭉 내려가면 바로 보여요.", "audio": "audio/e9bc2faeaa.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Straight down there, mate, all the way to the water.", "ko": "저리로 쭉, 물 나올 때까지요.", "audio": "audio/2ea2f52e77.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Left at the lights, then keep going till you hit the harbour.", "ko": "신호등에서 왼쪽, 항구 나올 때까지 쭉.", "audio": "audio/aa2ff3481b.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "It's that way, love, about ten minutes.", "ko": "저쪽이에요, 10분쯤.", "audio": "audio/4c93684fb7.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Down the hill, dear. Follow the ferries.", "ko": "언덕 아래로 가요. 페리 보이는 쪽으로.", "audio": "audio/12de29b873.mp3"}, {"speaker": "WH_IT", "speaker_label": "워홀러 (이탈리아)", "en": "I think it's that way? Maybe check Google Maps.", "ko": "저쪽 같은데요? 구글맵도 확인해보세요.", "audio": "audio/ef58611da6.mp3"}]}, {"situation": "걸어갈 만해요?", "order": "me", "speak": {"en": "Is it walkable from here?", "ko": "여기서 걸어갈 만해요?", "tip": "", "audio": "audio/4f7ce2be52.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yeah, it's like ten minutes, easy.", "ko": "네, 한 10분? 금방이에요.", "audio": "audio/68dc7dc5c4.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Nah, it's a bit of a hike. I'd jump on the train.", "ko": "아뇨, 꽤 멀어요. 저라면 기차 타요.", "audio": "audio/5160b348f1.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "You can walk it, mate. Fifteen minutes, tops.", "ko": "걸어가도 돼요. 길어야 15분.", "audio": "audio/a352efe99d.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "It's a fair way, love. I'd get the bus.", "ko": "꽤 멀어요. 버스 타세요.", "audio": "audio/54ac1d24c4.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Oh, I'd take the bus, dear. It's all uphill.", "ko": "버스 타요. 계속 오르막이에요.", "audio": "audio/d36526a17d.mp3"}]}, {"situation": "이 버스 본다이 가요? (기사님께)", "order": "me", "speak": {"en": "Hi, does this go to Bondi Beach?", "ko": "안녕하세요, 이거 본다이 비치 가요?", "tip": "333번. 정류장에서 손 들어 세우고, 탈 때 카드 찍기", "audio": "audio/4c23f48cdb.mp3"}, "hear": [{"speaker": "MM", "speaker_label": "중년 남성", "en": "Yep, hop on.", "ko": "네, 타세요.", "audio": "audio/7561853a74.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Not this one, love. You want the 333.", "ko": "이건 아니에요. 333번 타요.", "audio": "audio/ab0c5d0acd.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yeah, mate. Tap on there.", "ko": "네. 거기 카드 찍어요.", "audio": "audio/7a0d689a8e.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "This one goes to Bondi Junction, dear, not the beach.", "ko": "이건 본다이 정션 가요, 해변 말고.", "audio": "audio/e78ced86fa.mp3"}]}, {"situation": "도착하면 알려주실래요?", "order": "me", "speak": {"en": "Could you let us know when we get to Bondi?", "ko": "본다이 도착하면 알려주실래요?", "tip": "", "audio": "audio/7208b30f18.mp3"}, "hear": [{"speaker": "MM", "speaker_label": "중년 남성", "en": "Yeah, no worries. I'll give you a shout.", "ko": "그래요, 소리쳐 알려줄게요.", "audio": "audio/25a892db5b.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Sure, love. It's the last stop anyway.", "ko": "그래요. 어차피 종점이에요.", "audio": "audio/4be937779d.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Easy. It's about twenty minutes.", "ko": "그럼요. 20분쯤 걸려요.", "audio": "audio/06afcceed6.mp3"}]}, {"situation": "헤매고 있으면 먼저 말 걸어줘요", "order": "they", "speak": {"en": "Yes, please! We're trying to get to The Rocks.", "ko": "네! 더 록스 가려고요.", "tip": "괜찮으면 'All good, thanks!'", "audio": "audio/6a33928c55.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "You guys lost?", "ko": "길 잃으셨어요?", "audio": "audio/fd463c1120.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Need a hand?", "ko": "도와줄까요?", "audio": "audio/2967793d81.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Where you trying to get to, mate?", "ko": "어디 가려고요?", "audio": "audio/6dcbbc64c3.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "You right there, love? You look a bit lost.", "ko": "괜찮아요? 좀 헤매는 것 같은데.", "audio": "audio/f6f1db606e.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Can I help you find something, dears?", "ko": "뭐 찾는 거 도와줄까요?", "audio": "audio/88569a5584.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "You alright? Need directions?", "ko": "괜찮아요? 길 알려줄까요?", "audio": "audio/b6b04ea1ab.mp3"}]}, {"situation": "근처에 마트 있어요?", "order": "me", "speak": {"en": "Is there a supermarket around here?", "ko": "근처에 마트 있어요?", "tip": "Woolies(울워스) · Coles · IGA가 마트 이름이에요", "audio": "audio/16a1d30d92.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "There's a Woolies just up the road!", "ko": "길 위쪽에 울리스 있어요!", "audio": "audio/b987f01fd8.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Coles is in the basement of that centre.", "ko": "저 쇼핑센터 지하에 콜스 있어요.", "audio": "audio/f29ea19466.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "IGA on the corner, mate.", "ko": "모퉁이에 IGA 있어요.", "audio": "audio/13ab8ce04e.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Try the Woolworths at Town Hall, love.", "ko": "타운홀 울워스 가보세요.", "audio": "audio/232449c100.mp3"}, {"speaker": "WH_IT", "speaker_label": "워홀러 (이탈리아)", "en": "Yes, there is a Coles, two blocks that way.", "ko": "네, 저쪽 두 블록 가면 콜스 있어요.", "audio": "audio/f30c7775fc.mp3"}]}, {"situation": "서큘러 키 어떻게 가요? (여러 가지 대답)", "order": "me", "speak": {"en": "Sorry, how do I get to Circular Quay from here?", "ko": "저기요, 여기서 서큘러 키 어떻게 가요?", "tip": "hang a left = 왼쪽으로 돌다, the lights = 신호등, a fair way off = 꽤 멀다", "audio": "audio/9dd8f23bfc.mp3"}, "hear": [{"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Head straight down George Street, you can't miss it.", "ko": "조지 스트리트로 쭉 내려가면 바로 보여요.", "audio": "audio/2d127bd409.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Go up two blocks and hang a left at the lights.", "ko": "두 블록 가서 신호등에서 왼쪽으로 꺾어요.", "audio": "audio/0dcacfdbb8.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "It's about a ten-minute walk, just follow the signs.", "ko": "걸어서 10분쯤이에요, 표지판만 따라가요.", "audio": "audio/c6589b0e22.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Ah, you're a fair way off, mate. I'd grab the light rail.", "ko": "아, 꽤 멀리 왔네요. 저라면 경전철 타요.", "audio": "audio/667491d69f.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "Cross at the lights and it's on your right.", "ko": "신호등에서 건너면 오른쪽에 있어요.", "audio": "audio/258ddb6a13.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Just keep going till you hit the water, dear.", "ko": "물 나올 때까지 쭉 가요.", "audio": "audio/461a69b1bc.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Down to the end, love, then take a right at the station.", "ko": "끝까지 내려가서 역에서 오른쪽이에요.", "audio": "audio/10d08aed86.mp3"}]}, {"situation": "걸어갈 수 있는 거리예요?", "order": "me", "speak": {"en": "Is it walking distance?", "ko": "걸어갈 수 있는 거리예요?", "tip": "tops = 길어야, a bit of a hike = 꽤 걸어야 함, just round the corner = 바로 근처", "audio": "audio/291d359f9c.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yeah, five minutes tops.", "ko": "네, 길어야 5분이요.", "audio": "audio/529e328783.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Bit of a hike. I'd catch the bus.", "ko": "좀 멀어요. 저라면 버스 타요.", "audio": "audio/b2b52815c4.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Yes, it's just round the corner.", "ko": "네, 바로 모퉁이 돌면 있어요.", "audio": "audio/8873e37829.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "You could walk it, but it's all uphill, mate.", "ko": "걸어갈 순 있는데 계속 오르막이에요.", "audio": "audio/02ac986769.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "Hmm, like twenty minutes? Doable.", "ko": "음, 20분쯤? 걸을 만해요.", "audio": "audio/b8370fe69d.mp3"}]}, {"situation": "이 길 맞아요?", "order": "me", "speak": {"en": "Am I going the right way for the Opera House?", "ko": "오페라 하우스 가는데 이 길 맞아요?", "tip": "back that way = 왔던 쪽으로. 목적지만 바꿔서 쓰세요", "audio": "audio/6bb73d7c49.mp3"}, "hear": [{"speaker": "MF", "speaker_label": "중년 여성", "en": "You've gone past it, love. It's back that way.", "ko": "지나쳤어요. 왔던 쪽으로 돌아가요.", "audio": "audio/0a8ffee95f.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Yes, yes, keep going straight.", "ko": "네네, 계속 쭉 가요.", "audio": "audio/3bf806f698.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yep, you're right, mate. Two more minutes.", "ko": "네, 맞아요. 2분만 더 가요.", "audio": "audio/b215f76a74.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Nearly there, it's just past the gardens.", "ko": "거의 다 왔어요, 공원 바로 지나서예요.", "audio": "audio/7c07bc5a61.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Wrong way, dear. Turn around and follow the harbour.", "ko": "반대쪽이에요. 돌아서 항구 따라 가요.", "audio": "audio/c73e14717a.mp3"}]}]}, {"num": "3", "title": "쇼핑할 때", "lead": "점원은 꼭 먼저 말을 걸어요. 'Are you right?'은 '괜찮으세요?'가 아니라 '도와드릴까요?'예요.", "units": [{"situation": "도와드릴까요?", "order": "they", "speak": {"en": "Just looking, thanks.", "ko": "그냥 구경 중이에요.", "tip": "", "audio": "audio/4c11300dcc.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Hey! Are you looking for anything in particular?", "ko": "찾으시는 거 있어요?", "audio": "audio/d1c98784b1.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "How we goin'? Shout out if you need anything.", "ko": "필요한 거 있으면 불러요.", "audio": "audio/57f4c60796.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "G'day, you right there?", "ko": "도와드릴까요?", "audio": "audio/998f1dd293.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Hi there, are you right, or just browsing?", "ko": "도와드릴까요, 그냥 보세요?", "audio": "audio/051e32030e.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Have a good look, dear. No rush.", "ko": "천천히 보세요.", "audio": "audio/d65c05cfb0.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "Hi! Can I help you with anything?", "ko": "도와드릴까요?", "audio": "audio/8fff987a86.mp3"}]}, {"situation": "이거 다른 사이즈 있어요?", "order": "me", "speak": {"en": "Do you have this in a small?", "ko": "이거 스몰 있어요?", "tip": "small → medium / large / in black", "audio": "audio/a10c10fe6d.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Let me check out the back for you!", "ko": "창고 확인해볼게요!", "audio": "audio/88b00e474c.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Nah, sorry, that's all we've got.", "ko": "아뇨, 그게 다예요.", "audio": "audio/2d36e25739.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "I'll have a look in the back for you, love.", "ko": "뒤에 한번 볼게요.", "audio": "audio/5d49710126.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "I think we are sold out, sorry.", "ko": "품절인 것 같아요, 죄송해요.", "audio": "audio/7e43e910b7.mp3"}]}, {"situation": "입어봐도 돼요?", "order": "me", "speak": {"en": "Can I try this on?", "ko": "이거 입어봐도 돼요?", "tip": "탈의실 = change rooms", "audio": "audio/67594360a7.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yeah, totally! Change rooms are just there.", "ko": "그럼요! 탈의실은 저기요.", "audio": "audio/d0e010fcc6.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Of course, love. How many items have you got?", "ko": "그럼요. 몇 벌 가져가세요?", "audio": "audio/0cac901be0.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Go for it, mate. Just at the back.", "ko": "입어보세요. 뒤쪽이에요.", "audio": "audio/3dbbedec49.mp3"}]}, {"situation": "계산할 때 점원이 하는 말", "order": "they", "speak": {"en": "Card's fine, thanks.", "ko": "카드로 할게요.", "tip": "어떤 질문이 와도 카드 내밀면서 이 한 마디", "audio": "audio/e3e0596efb.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Just tap whenever you're ready!", "ko": "준비되면 카드 대세요!", "audio": "audio/cf24d28d02.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Tap there, mate.", "ko": "거기 찍어요.", "audio": "audio/947486a121.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Righto, that's forty-two fifty. Card?", "ko": "자, 42달러 50센트요. 카드죠?", "audio": "audio/00fb46d449.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Did you want a receipt with that, love?", "ko": "영수증 드릴까요?", "audio": "audio/ad9e6feb96.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "Tap or insert?", "ko": "대실래요, 꽂으실래요?", "audio": "audio/717011450b.mp3"}]}, {"situation": "봉투 필요하세요?", "order": "they", "speak": {"en": "No, I'm good, thanks.", "ko": "괜찮아요.", "tip": "'You right for a bag?' = 봉투 없어도 괜찮으세요? 봉투는 유료라 에코백 챙기기", "audio": "audio/4a98f6636d.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Did you need a bag for that?", "ko": "봉투 필요하세요?", "audio": "audio/2e4550f0a1.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "You right for a bag, mate?", "ko": "봉투 없어도 돼요?", "audio": "audio/255744d86f.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "You want a bag?", "ko": "봉투 드려요?", "audio": "audio/a33a14fa6e.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Bag?", "ko": "봉투?", "audio": "audio/50349eba4e.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Bags are fifteen cents, love, did you want one?", "ko": "봉투 15센트인데 드릴까요?", "audio": "audio/de98a2d79d.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "Do you need a bag?", "ko": "봉투 필요하세요?", "audio": "audio/8104c05247.mp3"}]}, {"situation": "TRS 세금 환급 영수증", "order": "me", "speak": {"en": "Could I get a tax invoice for the TRS?", "ko": "TRS 환급용 영수증 주실래요?", "tip": "한 가게 A$300 이상일 때만. 여권 지참", "audio": "audio/f1419785f6.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yep! Can I grab your name for it?", "ko": "네! 성함 알려주세요.", "audio": "audio/b2b32c00c5.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Of course. It's over three hundred, so you're all good.", "ko": "물론이죠. 300 넘으니 돼요.", "audio": "audio/884c0f3196.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Sure, I'll print one off.", "ko": "네, 하나 뽑아드릴게요.", "audio": "audio/fe408f7ca2.mp3"}]}, {"situation": "영수증 받기", "order": "me", "speak": {"en": "Can I grab a receipt, please?", "ko": "영수증 받을 수 있을까요?", "tip": "grab = get. 호주에선 'Can I grab ~?'을 정말 많이 써요. 영수증은 달라고 해야 주는 곳이 많아요", "audio": "audio/065cae6989.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yep! Printed or emailed?", "ko": "네! 종이로요, 이메일로요?", "audio": "audio/29b8725c87.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Sure, mate. There you go.", "ko": "네, 여기요.", "audio": "audio/9d6b5ed701.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Of course, love. I'll pop it in the bag.", "ko": "그럼요, 봉투에 넣어드릴게요.", "audio": "audio/f87f2c49d5.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "Yes, yes, receipt is coming. One second.", "ko": "네네, 영수증 나와요. 잠깐만요.", "audio": "audio/e40a6e0545.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "Course. Do you want it emailed?", "ko": "그럼요. 이메일로 드릴까요?", "audio": "audio/5b202f6a65.mp3"}]}, {"situation": "교환 · 환불", "order": "me", "speak": {"en": "Could I swap this for a different size?", "ko": "이거 다른 사이즈로 바꿀 수 있을까요?", "tip": "환불은 'Could I get a refund on this?' 영수증 꼭 챙기기. change of mind = 단순 변심", "audio": "audio/1009071f9a.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yep, have you got the receipt?", "ko": "네, 영수증 있으세요?", "audio": "audio/f4cf0dbc0e.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "No worries. What size were you after?", "ko": "그럼요. 무슨 사이즈 찾아요?", "audio": "audio/90a456ed20.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Of course, love. Tags still on?", "ko": "그럼요. 택 아직 붙어 있죠?", "audio": "audio/26847b9211.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "We can swap it, but no refunds for change of mind, sorry.", "ko": "교환은 되는데 단순 변심 환불은 안 돼요.", "audio": "audio/9eb4515139.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Yes, you have the receipt with you?", "ko": "네, 영수증 갖고 계세요?", "audio": "audio/7528af6c31.mp3"}]}, {"situation": "선물이에요? (포장)", "order": "they", "speak": {"en": "Yes, could you gift wrap it?", "ko": "네, 선물 포장해 주실래요?", "tip": "무료 포장이 많아요. 안 되면 gift bag이라도", "audio": "audio/102fe9302d.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Is it a gift?", "ko": "선물이에요?", "audio": "audio/15fedb2894.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Is this a present, love? I can wrap it for you.", "ko": "선물이에요? 포장해 드릴게요.", "audio": "audio/78dfaf21a2.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Want me to wrap that?", "ko": "포장해 드려요?", "audio": "audio/d17606093f.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "Would you like it gift-wrapped?", "ko": "선물 포장해 드릴까요?", "audio": "audio/c1a53bca78.mp3"}]}, {"situation": "플리마켓 흥정", "order": "me", "speak": {"en": "Could you do forty for both?", "ko": "둘 다 40에 안 될까요?", "tip": "빈티지·플리마켓에서만. 웃으면서 가볍게", "audio": "audio/3193f9d63e.mp3"}, "hear": [{"speaker": "MM", "speaker_label": "중년 남성", "en": "Go on then. Forty.", "ko": "에이, 그래요. 40.", "audio": "audio/fa7916cab5.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "I can do forty-five, love.", "ko": "45까진 해줄게요.", "audio": "audio/30f43f342a.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Oh, go on, since you asked nicely.", "ko": "착하게 물어봤으니 그래요.", "audio": "audio/7f95896eeb.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Sorry, mate, prices are firm.", "ko": "죄송한데 정가예요.", "audio": "audio/97119ee218.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "Cash only for that price, though.", "ko": "그 가격이면 현금만요.", "audio": "audio/937540b917.mp3"}]}, {"situation": "사이즈 묻기 (옷가게)", "order": "me", "speak": {"en": "Have you got this in a medium?", "ko": "이거 미디엄 있어요?", "tip": "S/M/L이 흔해요. 여성복 AU 8/10/12 ≈ 한국 44/55/66. 'out the back' = 창고", "audio": "audio/7739af49ea.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "What size are you after?", "ko": "무슨 사이즈 찾으세요?", "audio": "audio/37d8942389.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "That's the last one on the floor. I'll check out the back.", "ko": "매장엔 그게 마지막이에요. 창고 볼게요.", "audio": "audio/a22cece86c.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "Medium, yes, on the rack behind you.", "ko": "미디엄 있어요, 뒤에 걸려 있어요.", "audio": "audio/671c44603f.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Sorry, we've only got small and large left.", "ko": "죄송한데 스몰이랑 라지만 남았어요.", "audio": "audio/db6b5ee040.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Let me have a look for you, love.", "ko": "제가 찾아볼게요.", "audio": "audio/d0a8d5a7b0.mp3"}]}, {"situation": "다른 색 있어요?", "order": "me", "speak": {"en": "Does this come in any other colours?", "ko": "이거 다른 색도 있어요?", "tip": "colour는 호주식 철자. navy = 남색, khaki = 카키", "audio": "audio/ca9f6df2bc.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yeah, it comes in navy and khaki.", "ko": "네, 남색이랑 카키 있어요.", "audio": "audio/5812141d4b.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "That's all we've got in store, but there's more online.", "ko": "매장엔 그게 다인데 온라인에 더 있어요.", "audio": "audio/f40d471bb4.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Only black and white, sorry.", "ko": "검정이랑 흰색만 있어요, 죄송해요.", "audio": "audio/6907f4a213.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "Other colours are on that table there.", "ko": "다른 색은 저 테이블에 있어요.", "audio": "audio/25ab021850.mp3"}]}, {"situation": "남성복 어디예요?", "order": "me", "speak": {"en": "Where's the menswear section?", "ko": "남성복 코너 어디예요?", "tip": "down the back = 안쪽 끝, upstairs = 위층", "audio": "audio/721442b84a.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "Menswear's upstairs, past the escalators.", "ko": "남성복은 위층, 에스컬레이터 지나서요.", "audio": "audio/e157166157.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Men's is down the back on the left.", "ko": "남성복은 안쪽 끝 왼쪽이요.", "audio": "audio/72ebed8d3d.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Level two, love. Take the lift just there.", "ko": "2층이에요. 저기 엘리베이터 타요.", "audio": "audio/65f88c7492.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "It's in the basement, next to shoes.", "ko": "지하에 있어요, 신발 옆이요.", "audio": "audio/1963487c88.mp3"}]}, {"situation": "탈의실 어디예요? (여성복)", "order": "me", "speak": {"en": "Where are the change rooms?", "ko": "탈의실 어디예요?", "tip": "호주는 fitting rooms보다 change rooms. 여성복 = womenswear", "audio": "audio/6d37dcb433.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Change rooms are just behind the counter. How many items have you got?", "ko": "탈의실은 카운터 바로 뒤예요. 몇 벌 가져가세요?", "audio": "audio/3ff5879135.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Womenswear's on level one, the change rooms are up there.", "ko": "여성복은 1층이고 탈의실도 거기 있어요.", "audio": "audio/31d3bbab7d.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "Back corner, madam. Maximum five items.", "ko": "뒤쪽 구석이에요. 최대 다섯 벌이요.", "audio": "audio/0cf40aca9a.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Just at the back. Grab a number tag from me first.", "ko": "뒤쪽이요. 먼저 번호표 받아가세요.", "audio": "audio/2a91f86563.mp3"}]}]}, {"num": "4", "title": "음식 주문할 때 (카페 · 식당)", "lead": "카페는 사이즈 → 메뉴 → 우유 순서. 아메리카노 대신 롱블랙. 계산서는 bill, 포장은 takeaway. 팁은 안 줘도 돼요.", "units": [{"situation": "주문 받을 때", "order": "they", "speak": {"en": "Can I get a flat white and a long black, please?", "ko": "플랫화이트 하나랑 롱블랙 하나요.", "tip": "롱블랙 ≈ 진한 아메리카노", "audio": "audio/3a68bc8c13.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Hi! What can I get you?", "ko": "뭐 드릴까요?", "audio": "audio/dde211a054.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "What are we having today?", "ko": "오늘 뭐 드실래요?", "audio": "audio/91968fb137.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "What'll it be, mate?", "ko": "뭘로 할래요?", "audio": "audio/e268c592db.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "What can I get for you, love?", "ko": "뭐 드릴까요?", "audio": "audio/ebfbe0f2f6.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Now, what would you like, dears?", "ko": "자, 뭐 드시겠어요?", "audio": "audio/c2469631a7.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Hi there, what can I get for you?", "ko": "뭐 드릴까요?", "audio": "audio/cdcc742e01.mp3"}]}, {"situation": "먹고 가요, 포장이에요?", "order": "they", "speak": {"en": "Having here, thanks.", "ko": "먹고 갈게요.", "tip": "포장이면 'Takeaway, thanks.'", "audio": "audio/5d28fc2a15.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Is that for here?", "ko": "여기서 드세요?", "audio": "audio/9e861b5b51.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Having here?", "ko": "드시고 가요?", "audio": "audio/e19733996e.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Eat in or takeaway?", "ko": "먹고 가요, 가져가요?", "audio": "audio/08f20e67ed.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Dine in or takeaway, love?", "ko": "드시고 가세요, 포장이세요?", "audio": "audio/29dea3f674.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "For here or takeaway?", "ko": "여기서요, 포장이요?", "audio": "audio/4054dfacc8.mp3"}]}, {"situation": "우유 뭘로 할까요?", "order": "they", "speak": {"en": "Regular milk's fine.", "ko": "그냥 일반 우유요.", "tip": "oat / soy / almond / skinny(저지방)", "audio": "audio/b9d6f41b67.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Any milk preference?", "ko": "원하는 우유 있어요?", "audio": "audio/3aecabb694.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Full cream okay?", "ko": "일반 우유 괜찮죠?", "audio": "audio/69ff104a04.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Normal milk, love?", "ko": "일반 우유요?", "audio": "audio/b44a5c988f.mp3"}]}, {"situation": "이름 알려주세요", "order": "they", "speak": {"en": "It's Lee. L-E-E.", "ko": "Lee예요. 엘, 이, 이.", "tip": "짧은 영어 이름을 하나 정해두면 편해요", "audio": "audio/e353acd370.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Can I grab a name for that?", "ko": "성함 알려주실래요?", "audio": "audio/690c918a13.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Name for the order?", "ko": "주문 이름은요?", "audio": "audio/5673a50720.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "And what's the name?", "ko": "이름은요?", "audio": "audio/96962408fa.mp3"}]}, {"situation": "식당 입구에서", "order": "they", "speak": {"en": "Hi, we've got a booking for seven-thirty, under Lee.", "ko": "7시 반에 Lee로 예약했어요.", "tip": "예약 없으면 'Table for two, please.'", "audio": "audio/39b29bd759.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Hi guys! Just the two of you tonight?", "ko": "안녕하세요! 오늘 두 분이세요?", "audio": "audio/0a37e7cd9a.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Evening. Have you got a booking?", "ko": "안녕하세요. 예약하셨어요?", "audio": "audio/b16602fed9.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Welcome! Is there a booking under a name?", "ko": "어서 오세요! 예약 성함이요?", "audio": "audio/65199fd8b3.mp3"}, {"speaker": "WH_DE", "speaker_label": "워홀러 (독일)", "en": "Hi, do you have a reservation?", "ko": "예약하셨어요?", "audio": "audio/36013219b0.mp3"}]}, {"situation": "여기 주문은 어디서 해요?", "order": "me", "speak": {"en": "Do we order here or at the counter?", "ko": "주문 여기서 해요, 카운터에서 해요?", "tip": "펍·캐주얼 식당은 카운터 주문이 많아요", "audio": "audio/64fd725b2a.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "Order up at the bar, mate. Grab a number.", "ko": "바에서 주문하고 번호표 가져가요.", "audio": "audio/5128716b10.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "Just scan the QR code on the table!", "ko": "테이블 QR 찍으면 돼요!", "audio": "audio/7083c2f6ad.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "I'll come take your order, love.", "ko": "제가 주문 받으러 갈게요.", "audio": "audio/2cf054068e.mp3"}]}, {"situation": "뭐가 맛있어요?", "order": "me", "speak": {"en": "What's good here?", "ko": "여기 뭐가 맛있어요?", "tip": "", "audio": "audio/1cdbfb9e01.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Oh my god, the chilli scrambled eggs are amazing.", "ko": "칠리 스크램블 진짜 맛있어요.", "audio": "audio/f3822e590c.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Can't go past the burger, mate.", "ko": "버거는 꼭 먹어야죠.", "audio": "audio/79ed1afed9.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "The prime rib's the go.", "ko": "프라임립이 정답이죠.", "audio": "audio/9dde04035a.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Everyone loves the barramundi.", "ko": "다들 바라문디 좋아해요.", "audio": "audio/71817b3657.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "People really like the pasta, to be honest.", "ko": "솔직히 파스타 많이 시켜요.", "audio": "audio/d8484f2bff.mp3"}]}, {"situation": "고기 굽기 어떻게 할까요?", "order": "they", "speak": {"en": "Medium-rare, please.", "ko": "미디엄 레어요.", "tip": "rare / medium / well done", "audio": "audio/0003804a22.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "And how would you like that cooked?", "ko": "굽기는 어떻게 해드릴까요?", "audio": "audio/13ae3adbb7.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "How do you want your steak?", "ko": "스테이크 어떻게 해줄까요?", "audio": "audio/8e3f3b18fd.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "Which cooking for the steak?", "ko": "스테이크 굽기는요?", "audio": "audio/d805a8a177.mp3"}]}, {"situation": "물·음료 뭐 드릴까요?", "order": "they", "speak": {"en": "Just tap water, thanks. Have you got any mocktails?", "ko": "수돗물이요. 무알코올 칵테일 있어요?", "tip": "수돗물은 무료. 술 안 마시면 mocktail", "audio": "audio/ef7bb10d96.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Still or sparkling?", "ko": "생수요, 탄산수요?", "audio": "audio/bddbc788bd.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Can I get you guys anything to drink?", "ko": "음료 드릴까요?", "audio": "audio/ce836ee50a.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Something to drink, or just water?", "ko": "음료요, 물이요?", "audio": "audio/0470cda0b3.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Drinks to start?", "ko": "음료 먼저?", "audio": "audio/4f68f22452.mp3"}]}, {"situation": "식사 중에 '괜찮으세요?'", "order": "they", "speak": {"en": "Really good, thanks!", "ko": "정말 맛있어요!", "tip": "", "audio": "audio/4c65832676.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "How is everything?", "ko": "괜찮으세요?", "audio": "audio/dab19d3a08.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "How we going here?", "ko": "괜찮아요?", "audio": "audio/41ef91f6d9.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "How's it all tasting?", "ko": "맛은 괜찮아요?", "audio": "audio/45760bfe2c.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Everything alright for you, dears?", "ko": "다 괜찮아요?", "audio": "audio/dec357137e.mp3"}]}, {"situation": "계산할게요", "order": "me", "speak": {"en": "Could we get the bill, please?", "ko": "계산서 주세요.", "tip": "check보다 bill", "audio": "audio/2da7926774.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yep, I'll bring it right over!", "ko": "네, 바로 가져갈게요!", "audio": "audio/5dc0468213.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "You can just pay up at the counter.", "ko": "카운터에서 계산하시면 돼요.", "audio": "audio/77e9d4c323.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Together or separate, love?", "ko": "같이요, 따로요?", "audio": "audio/b259f79325.mp3"}]}, {"situation": "펍 · 카운터 주문: 테이블 번호", "order": "they", "speak": {"en": "Table twelve.", "ko": "12번 테이블이요.", "tip": "테이블에 번호 막대가 있어요. 음식은 자리로 가져다줘요", "audio": "audio/61e835b5e2.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "What table are you on?", "ko": "몇 번 테이블이세요?", "audio": "audio/8fa4738028.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Table number?", "ko": "테이블 번호요?", "audio": "audio/d0d96d0bce.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Where you sitting, mate?", "ko": "어디 앉았어요?", "audio": "audio/13d2824ef6.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "And which table's that for?", "ko": "몇 번 테이블로 드릴까요?", "audio": "audio/714b74d993.mp3"}]}, {"situation": "알레르기 있어요", "order": "me", "speak": {"en": "I'm allergic to peanuts. Is there any in this?", "ko": "땅콩 알레르기 있는데, 이거 들어가요?", "tip": "nuts · shellfish(갑각류) · dairy로 바꿔 쓰기. 메뉴의 GF = 글루텐 프리, V = 채식", "audio": "audio/b04e082a10.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Let me double-check with the kitchen for you!", "ko": "주방에 확인해 볼게요!", "audio": "audio/2c5835af83.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Nah, you're right. No nuts in that one.", "ko": "아뇨, 괜찮아요. 그건 견과류 없어요.", "audio": "audio/c2f292d531.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "It's got a satay sauce, love, so I'd steer clear.", "ko": "사테 소스(땅콩)라서 피하세요.", "audio": "audio/504531a444.mp3"}, {"speaker": "WH_IT", "speaker_label": "워홀러 (이탈리아)", "en": "I check with the chef, one moment.", "ko": "셰프한테 확인할게요, 잠시만요.", "audio": "audio/6f8473fabc.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "I'll pop a note on the order for the chef.", "ko": "주문에 셰프용 메모 남길게요.", "audio": "audio/4a378f4d4d.mp3"}]}, {"situation": "남은 음식 싸 가기", "order": "me", "speak": {"en": "Can I get a box for this?", "ko": "이거 싸 갈 수 있을까요?", "tip": "doggy bag보다 'a box' 'a container'가 자연스러워요", "audio": "audio/ecfddd742d.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Of course! I'll box it up for you.", "ko": "그럼요! 담아 드릴게요.", "audio": "audio/8712f231de.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yeah, no worries, I'll grab you a container.", "ko": "네, 용기 갖다 드릴게요.", "audio": "audio/398aa2193e.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Too easy. Want the sauce in there too?", "ko": "그럼요. 소스도 넣어줄까요?", "audio": "audio/d09e2bdfb4.mp3"}, {"speaker": "IN_SHOP", "speaker_label": "점원 (인도계)", "en": "Yes, I'll bring a takeaway box.", "ko": "네, 포장 용기 가져올게요.", "audio": "audio/3fb1753f96.mp3"}, {"speaker": "WH_DE", "speaker_label": "워홀러 (독일)", "en": "Sure, I bring you a box.", "ko": "네, 박스 갖다 드릴게요.", "audio": "audio/690f7c74ba.mp3"}]}, {"situation": "따로 계산 (더치페이)", "order": "me", "speak": {"en": "Could we split the bill?", "ko": "계산 나눠서 할 수 있을까요?", "tip": "친구들과 먹을 때. 'My shout!' = 제가 살게요", "audio": "audio/9f4de64cf4.mp3"}, "hear": [{"speaker": "MF", "speaker_label": "중년 여성", "en": "Sure, love. Down the middle?", "ko": "그럼요. 반반이요?", "audio": "audio/a0d1d4f52c.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "Yep, just tap one card at a time!", "ko": "네, 카드 하나씩 대세요!", "audio": "audio/53f052f4f9.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Half each, or what you each had?", "ko": "반씩요, 먹은 대로요?", "audio": "audio/2632151d17.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Sorry, mate, it's one bill per table.", "ko": "죄송한데 테이블당 한 번만 계산돼요.", "audio": "audio/16413ddf6a.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "No bother. How do you want to split it?", "ko": "그럼요. 어떻게 나눌까요?", "audio": "audio/b90fddb12f.mp3"}]}]}, {"num": "5", "title": "우리 일정에 꼭 나오는 장면", "lead": "신혼여행 가이드(11/3–11/8)를 보고 4가지 상황 말고 실제로 겪을 장면을 골랐어요.", "units": [{"situation": "11/3 입국 심사 · 여행 목적", "order": "they", "speak": {"en": "We're here on our honeymoon.", "ko": "신혼여행 왔어요.", "tip": "", "audio": "audio/c0f68cd95e.mp3"}, "hear": [{"speaker": "MF", "speaker_label": "중년 여성", "en": "What brings you to Australia?", "ko": "호주엔 무슨 일로 오셨어요?", "audio": "audio/b42b4eea4b.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Business or holiday?", "ko": "출장이에요, 여행이에요?", "audio": "audio/32160b6aa1.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Here on holiday?", "ko": "여행 오셨어요?", "audio": "audio/5f92ae57a3.mp3"}]}, {"situation": "11/3 세관 · 신고할 것", "order": "they", "speak": {"en": "Yes, just some snacks and medicine.", "ko": "네, 과자랑 약이요.", "tip": "신고하면 대부분 통과", "audio": "audio/433d94214b.mp3"}, "hear": [{"speaker": "MM", "speaker_label": "중년 남성", "en": "Anything to declare?", "ko": "신고할 것 있어요?", "audio": "audio/2f47b11041.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Any food or medication in your bags today?", "ko": "가방에 음식이나 약 있어요?", "audio": "audio/1e8c2a2ff0.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "Are you carrying any food?", "ko": "음식 갖고 계세요?", "audio": "audio/b5648c0e1d.mp3"}]}, {"situation": "11/3 공항 택시", "order": "me", "speak": {"en": "Four Seasons on George Street, please. That's the flat rate, right?", "ko": "조지 스트리트 포시즌스요. 정액 맞죠?", "tip": "공항→시내 정액 A$60", "audio": "audio/16e48e09cd.mp3"}, "hear": [{"speaker": "MM", "speaker_label": "중년 남성", "en": "Yep, sixty bucks flat to the city.", "ko": "네, 시내까지 60달러 정액.", "audio": "audio/ee85d8d49b.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yeah, sixty, plus a bit for card.", "ko": "네, 60에 카드 수수료 조금.", "audio": "audio/0af37f8a39.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "That's right. Pop your bags in the boot.", "ko": "맞아요. 짐은 트렁크에.", "audio": "audio/615b0c9fc6.mp3"}]}, {"situation": "11/3·11/4 호텔 · 짐 맡기기", "order": "me", "speak": {"en": "We're a bit early. Can we leave our bags here?", "ko": "좀 일찍 왔는데 짐 맡겨도 돼요?", "tip": "", "audio": "audio/4b0bb975e8.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Absolutely! I'll pop them in the luggage room.", "ko": "그럼요! 짐 보관실에 둘게요.", "audio": "audio/9f5df6c667.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "No worries. Here's your ticket.", "ko": "네. 보관표 여기요.", "audio": "audio/8f5019d053.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Of course. Your room should be ready by three.", "ko": "물론이죠. 방은 3시쯤 준비돼요.", "audio": "audio/21157e9ddd.mp3"}]}, {"situation": "호텔 체크인 · 보증금 카드", "order": "they", "speak": {"en": "Sure, here's my card.", "ko": "네, 카드 여기요.", "tip": "incidentals · hold · pre-authorisation = 보증금 가승인. 체크아웃 며칠 뒤 풀려요", "audio": "audio/00fef1d071.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Can I just grab a card for incidentals?", "ko": "부대비용용 카드 하나 주시겠어요?", "audio": "audio/ad4ae7727e.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "We'll pop a two-hundred-dollar hold on your card. It drops off after checkout.", "ko": "카드에 200달러 가승인 걸고, 체크아웃 후 풀려요.", "audio": "audio/c2a4a2fb7f.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "And just a credit card for any extras, love?", "ko": "추가 요금용 신용카드도 주세요.", "audio": "audio/484a1b4405.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "I just need to take a card for the security deposit.", "ko": "보증금용 카드만 받을게요.", "audio": "audio/de91a1f8a1.mp3"}]}, {"situation": "신혼여행이라고 하면", "order": "they", "speak": {"en": "Thank you so much!", "ko": "정말 고마워요!", "tip": "", "audio": "audio/f9c0051163.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Oh my god, congrats! That's so exciting!", "ko": "어머 축하해요! 너무 좋겠다!", "audio": "audio/9e95dd24bd.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Legend! Congrats, mate.", "ko": "멋지다! 축하해요.", "audio": "audio/bb657bf9bc.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Good on ya! Congratulations.", "ko": "잘했네요! 축하해요.", "audio": "audio/b528e54eb6.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Oh, how lovely! Congratulations, you two.", "ko": "어머 좋아라! 두 분 축하해요.", "audio": "audio/dde69b5967.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Congratulations, dears. Enjoy every minute.", "ko": "축하해요. 매 순간 즐겨요.", "audio": "audio/1a57585f2f.mp3"}, {"speaker": "WH_IE", "speaker_label": "워홀러 (아일랜드)", "en": "Aw, congrats! Have the best time!", "ko": "축하해요! 최고의 시간 보내요!", "audio": "audio/21308e8872.mp3"}]}, {"situation": "사진 부탁", "order": "me", "speak": {"en": "Would you mind taking a photo of us?", "ko": "사진 좀 찍어주실래요?", "tip": "", "audio": "audio/b50cccf428.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Of course! Want the Opera House in it?", "ko": "그럼요! 오페라하우스 나오게요?", "audio": "audio/c21d442a03.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yeah, sweet. Landscape or portrait?", "ko": "좋아요. 가로요, 세로요?", "audio": "audio/2abbd8c72c.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Oh, of course, love. Say cheese!", "ko": "그럼요. 치즈~", "audio": "audio/77523c0dee.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "I'll try, dear. Which button do I press?", "ko": "해볼게요. 어느 버튼 눌러요?", "audio": "audio/a676687822.mp3"}]}, {"situation": "11/6 페더데일 · 만져도 돼요?", "order": "me", "speak": {"en": "Are we allowed to pat them?", "ko": "쓰다듬어도 돼요?", "tip": "pat = 쓰다듬다", "audio": "audio/e20022ad42.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Yep, gently on the back, not the head.", "ko": "네, 등만 살살, 머리는 안 돼요.", "audio": "audio/53fd66af35.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Two fingers, mate. Nice and gentle.", "ko": "손가락 두 개로 살살요.", "audio": "audio/81d5ccda96.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Not this one, love, but the kangaroos are fine.", "ko": "얘는 안 되고 캥거루는 돼요.", "audio": "audio/a7726d78cb.mp3"}]}, {"situation": "11/7 아이스버그 수영장 입장", "order": "me", "speak": {"en": "Hi, two adults, please.", "ko": "성인 두 명이요.", "tip": "입장료에 사우나 포함", "audio": "audio/8344609963.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "That's twenty. Towels are five each if you need 'em.", "ko": "20달러요. 수건은 하나 5달러.", "audio": "audio/0b484e64db.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Sauna's downstairs, love. Fifteen minutes max.", "ko": "사우나는 아래층, 최대 15분이에요.", "audio": "audio/2b0ce56dad.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "Heads up, the water's pretty fresh today!", "ko": "오늘 물 꽤 차가워요!", "audio": "audio/6f75f93c26.mp3"}]}, {"situation": "본다이 · 맨리 해변 · 라이프가드", "order": "they", "speak": {"en": "Oh, sorry! Thanks.", "ko": "아, 죄송해요! 고마워요.", "tip": "빨강·노랑 깃발 사이에서만 수영. rip = 이안류", "audio": "audio/06c6aa1b63.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "Swim between the flags, mate!", "ko": "깃발 사이에서 수영해요!", "audio": "audio/543ec71828.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Oi! Back between the flags!", "ko": "어이! 깃발 사이로 돌아와요!", "audio": "audio/0d4b6332c8.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "Hey guys, can you move between the red and yellow flags?", "ko": "빨강·노랑 깃발 사이로 옮겨 주실래요?", "audio": "audio/8aa0c4b1e3.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Rip's pretty strong today, love. Stick between the flags.", "ko": "오늘 이안류 세요. 깃발 사이에 있어요.", "audio": "audio/9bc0eb5a42.mp3"}]}, {"situation": "약국 (chemist)", "order": "me", "speak": {"en": "Have you got anything for seasickness?", "ko": "뱃멀미약 있어요?", "tip": "headache / sunburn / a cold 로 바꿔 쓰기", "audio": "audio/42d9701894.mp3"}, "hear": [{"speaker": "MF", "speaker_label": "중년 여성", "en": "Are you taking any other medication?", "ko": "다른 약 드시는 거 있어요?", "audio": "audio/38c88bfed7.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "These ones. Take one half an hour before.", "ko": "이거요. 30분 전에 하나.", "audio": "audio/1e2fab7b31.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Make sure you have something to eat first, dear.", "ko": "먼저 뭘 좀 드시고 드세요.", "audio": "audio/b52e4b6ff8.mp3"}]}, {"situation": "날씨 스몰토크", "order": "they", "speak": {"en": "Yeah, it's beautiful!", "ko": "그러게요, 날씨 좋네요!", "tip": "추우면 'Yeah, bit chilly!'", "audio": "audio/16b5b6a421.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "Stinker today, eh?", "ko": "오늘 덥죠?", "audio": "audio/3a6e4b9c90.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Bit fresh this morning.", "ko": "아침엔 좀 쌀쌀하네요.", "audio": "audio/8f7bd6fd00.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Gorgeous day for it!", "ko": "날씨 끝내주네요!", "audio": "audio/ab8e8165a0.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "They reckon rain this arvo.", "ko": "오후에 비 온대요.", "audio": "audio/9f6de57386.mp3"}]}]}, {"num": "6", "title": "교통 · 매표소 (페리 · 기차 · 택시 · 우버)", "lead": "교통 직원·기사님은 짧게 말해요: Where you headed?(어디 가요?), Return?(왕복?), Tap on(카드 찍어요). 한 사람당 카드 한 장, 탈 때·내릴 때 같은 카드로 찍어요.", "units": [{"situation": "맨리 페리 몇 번 부두예요?", "order": "me", "speak": {"en": "Sorry, which wharf for the Manly ferry?", "ko": "맨리 페리 몇 번 부두예요?", "tip": "wharf = 부두. 맨리행은 서큘러 키 3번 부두. 전광판도 확인", "audio": "audio/04e85493ce.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Wharf three, just over there!", "ko": "3번 부두, 바로 저기요!", "audio": "audio/29c767e8d5.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Three, mate. Next one's in ten minutes.", "ko": "3번이요. 다음 배 10분 뒤.", "audio": "audio/2fb16541ed.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "It's wharf three, love. Just follow the signs for Manly.", "ko": "3번 부두예요. 맨리 표지 따라가요.", "audio": "audio/ac85d96ca7.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Number three, dear. The big green and yellow boat.", "ko": "3번이에요. 초록·노란 큰 배요.", "audio": "audio/f7b804e71e.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "Wharf three, I think. Have a look at the board.", "ko": "3번 같아요. 전광판 한번 보세요.", "audio": "audio/191edf6955.mp3"}]}, {"situation": "카드 찍기 (탭 온 · 탭 오프)", "order": "they", "speak": {"en": "Got it, thanks!", "ko": "알겠어요, 고마워요!", "tip": "교통카드 대신 컨택리스 카드·폰으로 탭. 한 사람당 카드 한 장, 탈 때·내릴 때 같은 카드로", "audio": "audio/ed844898f8.mp3"}, "hear": [{"speaker": "YM", "speaker_label": "20대 남성", "en": "Don't forget to tap on, mate.", "ko": "카드 찍는 거 잊지 마요.", "audio": "audio/96cc231781.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Tap on there, love, and tap off when you get off.", "ko": "거기 찍고, 내릴 때도 찍어요.", "audio": "audio/663e9f8393.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "You'll each need your own card. You can't share one.", "ko": "한 사람당 카드 하나씩이에요. 같이 못 써요.", "audio": "audio/83212e5e3f.mp3"}, {"speaker": "YF", "speaker_label": "20대 여성", "en": "You've gotta tap off too, or it charges you the max!", "ko": "내릴 때도 찍어야 해요, 안 그러면 최대 요금 나가요!", "audio": "audio/4dccd26068.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Use the same card to tap off, dear.", "ko": "내릴 때도 같은 카드로 찍어요.", "audio": "audio/47178e308f.mp3"}]}, {"situation": "매표소 · 왕복이에요, 편도예요?", "order": "they", "speak": {"en": "Two returns, please.", "ko": "왕복 두 장이요.", "tip": "return = 왕복, single · one-way = 편도. 유람선·전용 페리 매표소에서 들어요", "audio": "audio/74bf68db7b.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Return or one-way?", "ko": "왕복이요, 편도요?", "audio": "audio/94be7003bc.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Just the one way?", "ko": "편도만요?", "audio": "audio/e869688c20.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Single or return, mate?", "ko": "편도요, 왕복이요?", "audio": "audio/1364662ee2.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Are you coming back with us, love, or just one way?", "ko": "돌아오는 것도 타세요, 편도만요?", "audio": "audio/a4aacd0e43.mp3"}, {"speaker": "WH_GB2", "speaker_label": "워홀러 (영국)", "en": "Is that a return?", "ko": "왕복이에요?", "audio": "audio/dbd6a9bf55.mp3"}, {"speaker": "WH_FR", "speaker_label": "워홀러 (프랑스)", "en": "One-way or return ticket?", "ko": "편도예요, 왕복이에요?", "audio": "audio/90a404589a.mp3"}]}, {"situation": "기차 몇 번 플랫폼이에요?", "order": "me", "speak": {"en": "Sorry, which platform for Central?", "ko": "센트럴 가려면 몇 번 플랫폼이에요?", "tip": "Central 대신 목적지 역 이름만 바꾸기", "audio": "audio/6373cfdb44.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "Platform two, it's the next one!", "ko": "2번이요, 다음 열차예요!", "audio": "audio/38ac7ddb34.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Either platform, mate. They all go through Central.", "ko": "아무 데나요. 다 센트럴 지나가요.", "audio": "audio/350f1920dc.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Platform one, love, just down those stairs.", "ko": "1번이요, 저 계단 아래요.", "audio": "audio/7a734d96c3.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Check the board, dear. It changes sometimes.", "ko": "전광판 봐요. 가끔 바뀌어요.", "audio": "audio/396e5cf690.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Same side, mate. Next one's in four minutes.", "ko": "이쪽이요. 다음 열차 4분 뒤.", "audio": "audio/41d626e78a.mp3"}]}, {"situation": "택시 잡기 · 빈 차예요?", "order": "me", "speak": {"en": "Hi, are you free?", "ko": "안녕하세요, 빈 차예요?", "tip": "지붕 불 켜진 택시가 빈 차. taxi rank = 택시 승강장, cab = 택시", "audio": "audio/a2600c45fb.mp3"}, "hear": [{"speaker": "IN_DRV", "speaker_label": "택시·우버 기사 (인도계)", "en": "Yes, yes, hop in.", "ko": "네네, 타세요.", "audio": "audio/e37a4fe0e0.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Yep, jump in, mate.", "ko": "네, 타요.", "audio": "audio/ddbb6f8f84.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Sorry, mate, I'm on my way to a job.", "ko": "미안해요, 예약 손님 가는 중이에요.", "audio": "audio/7715866d6d.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Sorry, love, you'll have to go to the rank round the corner.", "ko": "모퉁이 택시 승강장으로 가셔야 해요.", "audio": "audio/cb43e5e9a5.mp3"}]}, {"situation": "택시 타면 첫마디 · 어디 가요?", "order": "they", "speak": {"en": "The Four Seasons on George Street, please.", "ko": "조지 스트리트 포시즌스요.", "tip": "'Where you headed?' = 어디 가세요? (head = 가다)", "audio": "audio/819c5069fa.mp3"}, "hear": [{"speaker": "IN_DRV", "speaker_label": "택시·우버 기사 (인도계)", "en": "Where you headed?", "ko": "어디 가세요?", "audio": "audio/1330395c36.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Where to, mate?", "ko": "어디로요?", "audio": "audio/1944d7d462.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Where are we off to?", "ko": "어디 가요?", "audio": "audio/1c21b10f9c.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Where are we going today, love?", "ko": "오늘 어디 가세요?", "audio": "audio/15b152d8eb.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "Where can I take you?", "ko": "어디로 모실까요?", "audio": "audio/6903d73a83.mp3"}]}, {"situation": "우버 픽업 확인", "order": "they", "speak": {"en": "Yes, that's us. Hi!", "ko": "네, 저희예요. 안녕하세요!", "tip": "타기 전에 앱의 차 번호판 확인. 우버는 보통 뒷좌석에 타요", "audio": "audio/058c17821f.mp3"}, "hear": [{"speaker": "IN_DRV", "speaker_label": "택시·우버 기사 (인도계)", "en": "You Lee?", "ko": "Lee 씨예요?", "audio": "audio/e27c73c097.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Lee? Hop in.", "ko": "Lee? 타요.", "audio": "audio/137c5edc4e.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Hi, are you Lee?", "ko": "안녕하세요, Lee 씨죠?", "audio": "audio/95f061b25e.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Uber for Lee?", "ko": "Lee 씨 우버요?", "audio": "audio/3f2c52cf92.mp3"}, {"speaker": "WH_KR", "speaker_label": "워홀러 (한국)", "en": "Hi, Lee, right?", "ko": "안녕하세요, Lee 씨 맞죠?", "audio": "audio/8a35e65216.mp3"}]}, {"situation": "택시 내릴 때 · 카드 결제와 영수증", "order": "me", "speak": {"en": "Can I pay by card and grab a receipt?", "ko": "카드로 하고 영수증 받을 수 있을까요?", "tip": "NSW 택시는 카드 결제 시 최대 5% 수수료가 붙어요", "audio": "audio/950f5eaf43.mp3"}, "hear": [{"speaker": "IN_DRV", "speaker_label": "택시·우버 기사 (인도계)", "en": "Yes, tap here. Five percent extra on card, okay?", "ko": "네, 여기 대세요. 카드는 5% 추가돼요, 괜찮죠?", "audio": "audio/9ca77d0554.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "No worries. Tap there and I'll print one off.", "ko": "그럼요. 거기 찍으면 뽑아 줄게요.", "audio": "audio/bed6484a9c.mp3"}, {"speaker": "YM", "speaker_label": "20대 남성", "en": "Yep, just hit 'receipt' on the screen there.", "ko": "네, 화면에서 영수증 누르세요.", "audio": "audio/cfcf3a70f3.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "Course, love. Printed or emailed?", "ko": "그럼요. 종이요, 이메일이요?", "audio": "audio/533c687d98.mp3"}]}, {"situation": "공항에서 시내까지 · 기차 vs 택시", "order": "me", "speak": {"en": "What's the easiest way to get into the city?", "ko": "시내까지 제일 편하게 가는 방법이 뭐예요?", "tip": "공항 기차는 역 이용료가 따로 붙어요. 둘이 짐 많으면 택시(정액 A$60)도 비슷해요", "audio": "audio/1fc4cecde2.mp3"}, "hear": [{"speaker": "YF", "speaker_label": "20대 여성", "en": "The train's quickest. It's like fifteen minutes to Central.", "ko": "기차가 제일 빨라요. 센트럴까지 15분쯤.", "audio": "audio/f124bce0c8.mp3"}, {"speaker": "MM", "speaker_label": "중년 남성", "en": "Train's the go, mate, but it's not cheap with the station fee.", "ko": "기차가 낫죠. 근데 역 이용료 때문에 안 싸요.", "audio": "audio/cd55c78465.mp3"}, {"speaker": "MF", "speaker_label": "중년 여성", "en": "With all those bags, love, I'd just grab a cab.", "ko": "짐이 그렇게 많으면 그냥 택시 타요.", "audio": "audio/786b61cb0f.mp3"}, {"speaker": "OLD", "speaker_label": "어르신", "en": "There's a taxi rank right outside, dear.", "ko": "바로 밖에 택시 승강장 있어요.", "audio": "audio/0ae53dd65d.mp3"}, {"speaker": "WH_GB", "speaker_label": "워홀러 (영국)", "en": "Honestly, the train's easiest. Just tap your card.", "ko": "솔직히 기차가 제일 쉬워요. 카드만 찍으면 돼요.", "audio": "audio/fff56a55e1.mp3"}]}]}], "hear_words": [{"en": "arvo", "ko": "오후", "audio": "audio/cd3b0d7263.mp3"}, {"en": "brekkie", "ko": "아침식사", "audio": "audio/201b7fdac1.mp3"}, {"en": "heaps", "ko": "엄청 (very / a lot)", "audio": "audio/6da34c80b4.mp3"}, {"en": "reckon", "ko": "~인 것 같아", "audio": "audio/4dd4de17c6.mp3"}, {"en": "keen", "ko": "하고 싶은, 신난", "audio": "audio/33963107f4.mp3"}, {"en": "yeah, nah", "ko": "아니 (거절)", "audio": "audio/12bc958979.mp3"}, {"en": "nah, yeah", "ko": "응 (긍정)", "audio": "audio/7c45913b28.mp3"}, {"en": "no worries / no dramas / too easy", "ko": "괜찮아요 / 문제없어요", "audio": "audio/2a6a524296.mp3"}, {"en": "good on ya", "ko": "잘했어요 / 좋네요", "audio": "audio/e0093a92f8.mp3"}, {"en": "you right?", "ko": "도와드릴까요?", "audio": "audio/f8adc30b76.mp3"}, {"en": "love / dear / mate", "ko": "친근한 호칭 (중년·어르신이 love·dear)", "audio": "audio/8eb4f0e969.mp3"}, {"en": "fresh", "ko": "쌀쌀한", "audio": "audio/e8542ef54f.mp3"}, {"en": "stinker", "ko": "엄청 더운 날", "audio": "audio/646ae6b72f.mp3"}, {"en": "Maccas", "ko": "맥도날드", "audio": "audio/e449636fbf.mp3"}, {"en": "servo", "ko": "주유소", "audio": "audio/88aafa8aed.mp3"}, {"en": "bottle-o", "ko": "주류 판매점", "audio": "audio/3b598f3b25.mp3"}, {"en": "chemist", "ko": "약국", "audio": "audio/7af479baef.mp3"}, {"en": "thongs", "ko": "슬리퍼", "audio": "audio/605678d8dd.mp3"}, {"en": "sunnies", "ko": "선글라스", "audio": "audio/ba2e704f58.mp3"}, {"en": "swimmers / cossie", "ko": "수영복", "audio": "audio/a22a47ea75.mp3"}, {"en": "esky", "ko": "아이스박스", "audio": "audio/02b2db9ecd.mp3"}, {"en": "entrée", "ko": "애피타이저 (메인 아님)", "audio": "audio/2983eae7f3.mp3"}, {"en": "you're right", "ko": "괜찮아요 (사과에 대한 대답)", "audio": "audio/7638603391.mp3"}, {"en": "Where you headed?", "ko": "어디 가요?", "audio": "audio/67995fb9cf.mp3"}, {"en": "return / one-way", "ko": "왕복 / 편도", "audio": "audio/280c27e582.mp3"}, {"en": "tap on / tap off", "ko": "탈 때 / 내릴 때 카드 찍기", "audio": "audio/f89ea4dae4.mp3"}, {"en": "cab", "ko": "택시", "audio": "audio/35219df15d.mp3"}, {"en": "Woolies", "ko": "울워스 (마트)", "audio": "audio/32df8f306b.mp3"}, {"en": "my shout", "ko": "제가 살게요", "audio": "audio/2fe178ca28.mp3"}, {"en": "change of mind", "ko": "단순 변심 (환불 안 될 때)", "audio": "audio/fb2137b9f9.mp3"}], "videos": [{"title": "How To Start a Conversation in Australia", "ch": "mmmEnglish (호주인 Emma)", "len": "약 12분", "lang": "영어", "url": "https://www.youtube.com/watch?v=Wf1XtPyvknQ", "why": "택시·우버, 마트, 길 묻기, 사진 부탁을 따라 말하기로 연습. 1·2장과 짝.", "when": "10/28"}, {"title": "How to Order Coffee in Australia", "ch": "Learn Australian English (Jack & Liz)", "len": "약 8분", "lang": "영어", "url": "https://www.youtube.com/watch?v=Z6dPFKzg2QQ", "why": "'Have here or takeaway?'처럼 카페에서 듣는 말 그대로. 4장과 짝.", "when": "10/29"}, {"title": "호주 현지 카페사장님이 알려주는 카푸치노·플랫화이트·롱블랙 차이", "ch": "안스타 (한국어)", "len": "약 10분", "lang": "한국어", "url": "https://www.youtube.com/watch?v=s-vnVkOaYvE", "why": "롱블랙 vs 아메리카노, 플랫화이트 vs 라떼를 한국어로.", "when": "10/29"}, {"title": "28 Australian Slang Words/Phrases", "ch": "Welcome To Australia (거리 인터뷰)", "len": "약 6분", "lang": "영어", "url": "https://www.youtube.com/watch?v=RJ8ibvD2W6U", "why": "20대부터 중년까지 진짜 호주 사람들 목소리. 화자별 억양 차이 듣기에 최고.", "when": "10/30"}, {"title": "Australian English Conversation Practice – Slang I Use Every Day", "ch": "mmmEnglish", "len": "약 15분", "lang": "영어", "url": "https://www.youtube.com/watch?v=jrc8MAWVp1w", "why": "일상 대화 속 슬랭을 상황극으로.", "when": "11/2 기내"}, {"title": "50 Australian Words You Should Learn Your First Week", "ch": "Kinda Australian (시드니 거주 미국인)", "len": "약 11분", "lang": "영어", "url": "https://www.youtube.com/watch?v=5C7bk_ydt-w", "why": "시드니에 처음 온 외국인이 헷갈리는 말 위주. 2026년 영상.", "when": "11/2 기내"}], "plan": [["10/28 (수)", "0~2장 + 영상 1 · MP3 01~03", "15분"], ["10/29 (목)", "4장 음식 + 영상 2·3 · MP3 05 · 둘이 점원/손님 역할 바꿔보기", "15분"], ["10/30 (금)", "3장 쇼핑 + 6장 교통 + 영상 4 · MP3 04 · 07", "20분"], ["10/31 (토)", "결혼식! 쉬기", "—"], ["11/1 (일)", "5장 일정 장면 + 알아두기 · MP3 06", "15분"], ["11/2 (월)", "기내: 영상 5·6 + MP3 08 들리는 말 + 전체 듣기 한 번", "30분"]], "tips": [{"title": "팁", "text": "필수가 아니에요. 정말 좋았을 때만 10% 정도 선택. 계산서에 팁 칸이 떠도 'No tip'을 눌러도 돼요."}, {"title": "카드 수수료", "text": "2026년 10월 1일부터 가게·식당의 카드 수수료(surcharge)는 금지예요. 대신 식당은 주말·공휴일 할증(weekend / public holiday surcharge)을 메뉴에 적어 두고 받을 수 있어요."}, {"title": "택시 카드 결제", "text": "NSW 택시는 카드로 내면 최대 5% 수수료가 붙어요."}, {"title": "공항 → 시내 택시", "text": "시드니 공항에서 시내(CBD)까지 정액 A$60."}, {"title": "교통카드 대신 내 카드", "text": "오팔카드 없이 컨택리스 신용카드·폰으로 탭하면 오팔 요금과 같아요. 한 사람당 카드 한 장(둘이 한 카드 X), 탈 때·내릴 때 같은 카드로 tap on · tap off."}, {"title": "하루 교통비 상한", "text": "월–목 A$19.30, 금–일·공휴일 A$9.65까지만 나와요. (공항역 이용료는 따로)"}, {"title": "물", "text": "식당 수돗물(tap water)은 무료. 그냥 달라고 하면 병째 가져다줘요."}, {"title": "가격", "text": "가격표에 GST(부가세 10%)가 이미 포함돼 있어요. 계산대에서 더 붙지 않아요."}, {"title": "entrée", "text": "호주에선 '전채(애피타이저)'예요. 메인 요리는 main."}, {"title": "BYO", "text": "Bring Your Own: 술을 가져가도 되는 식당. 1인당 코키지(corkage) 요금이 있을 수 있어요."}, {"title": "shout", "text": "'My shout' = 제가 살게요. 'It's your shout' = 이번엔 네가 사."}, {"title": "봉투", "text": "마트·가게 봉투는 유료예요. 장바구니(에코백)를 챙기세요."}, {"title": "TRS 세금 환급", "text": "한 가게에서 A$300 이상(GST 포함) 산 영수증(tax invoice)이 있으면 출국 때 공항에서 환급. 출국 60일 이내 구매분, 물건은 기내에 들고 가기."}]};